# Review package: d079d0c012d78c933fc95ca6881c0957acb5b2fe..HEAD

## Commits
ec3ba0b Add greeting function with custom formatting
dfbe17b Add greeting implementation plan

## Files changed
 greet.js      | 29 +++++++++++++++++++++++++++++
 greet.test.js | 48 ++++++++++++++++++++++++++++++++++++++++++++++++
 plan.md       | 24 ++++++++++++++++++++++++
 3 files changed, 101 insertions(+)

## Diff
diff --git a/greet.js b/greet.js
new file mode 100644
index 0000000..d54aaf3
--- /dev/null
+++ b/greet.js
@@ -0,0 +1,29 @@
+function greet(name, options = {}) {
+  // Handle empty, null, or undefined input
+  const displayName = name || 'Guest';
+
+  // Extract options
+  const { prefix, suffix, uppercase } = options;
+
+  // Build the formatted name
+  let formattedName = displayName;
+
+  // Apply uppercase transformation if requested
+  if (uppercase) {
+    formattedName = formattedName.toUpperCase();
+  }
+
+  // Add prefix if provided
+  if (prefix) {
+    formattedName = `${prefix} ${formattedName}`;
+  }
+
+  // Add suffix if provided
+  if (suffix) {
+    formattedName = `${formattedName} ${suffix}`;
+  }
+
+  return `Hello, ${formattedName}!`;
+}
+
+module.exports = { greet };
diff --git a/greet.test.js b/greet.test.js
new file mode 100644
index 0000000..c53bd87
--- /dev/null
+++ b/greet.test.js
@@ -0,0 +1,48 @@
+const test = require('node:test');
+const assert = require('node:assert');
+const { greet } = require('./greet');
+
+test('greet returns formatted greeting with name', () => {
+  const result = greet('Alice');
+  assert.strictEqual(result, 'Hello, Alice!');
+});
+
+test('greet handles empty string gracefully', () => {
+  const result = greet('');
+  assert.strictEqual(result, 'Hello, Guest!');
+});
+
+test('greet handles null gracefully', () => {
+  const result = greet(null);
+  assert.strictEqual(result, 'Hello, Guest!');
+});
+
+test('greet handles undefined gracefully', () => {
+  const result = greet(undefined);
+  assert.strictEqual(result, 'Hello, Guest!');
+});
+
+test('greet with prefix option', () => {
+  const result = greet('Smith', { prefix: 'Dr.' });
+  assert.strictEqual(result, 'Hello, Dr. Smith!');
+});
+
+test('greet with suffix option', () => {
+  const result = greet('Johnson', { suffix: 'Jr.' });
+  assert.strictEqual(result, 'Hello, Johnson Jr.!');
+});
+
+test('greet with uppercase option', () => {
+  const result = greet('bob', { uppercase: true });
+  assert.strictEqual(result, 'Hello, BOB!');
+});
+
+test('greet with prefix, suffix, and uppercase', () => {
+  const result = greet('jones', { prefix: 'Dr.', suffix: 'PhD', uppercase: true });
+  assert.strictEqual(result, 'Hello, Dr. JONES PhD!');
+});
+
+test('greet with empty options object', () => {
+  const result = greet('Charlie', {});
+  assert.strictEqual(result, 'Hello, Charlie!');
+});
diff --git a/plan.md b/plan.md
new file mode 100644
index 0000000..3770877
--- /dev/null
+++ b/plan.md
@@ -0,0 +1,24 @@
+# Single-Task Greeting Plan
+
+**Spec:** Add a small greeting customization feature.
+
+**Goal:** The app can greet a provided name with custom formatting.
+
+---
